DO $$ DECLARE sig text; BEGIN FOREACH sig IN ARRAY ARRAY['public.record_member_holdings(jsonb,text,text,integer)','public.record_member_debts(jsonb,integer,text)','public.record_member_investment_scope(uuid,text,jsonb,integer,text)','portfolio_scope_private.record_review(uuid,text,jsonb,integer,text)'] LOOP IF has_function_privilege('authenticated',sig,'EXECUTE') OR has_function_privilege('anon',sig,'EXECUTE') THEN RAISE EXCEPTION 'writer freeze assertion failed'; END IF; END LOOP; IF has_table_privilege('authenticated','public.research_workbook_versions','INSERT') OR has_table_privilege('authenticated','public.research_workbook_reviews','INSERT') OR has_table_privilege('anon','public.research_workbook_versions','INSERT') THEN RAISE EXCEPTION 'research freeze assertion failed'; END IF; IF NOT has_table_privilege('authenticated','public.research_workbook_versions','SELECT') OR NOT has_table_privilege('authenticated','public.research_workbook_reviews','SELECT') THEN RAISE EXCEPTION 'research read preservation failed'; END IF; IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='holdings' AND (coalesce(qual,'') || coalesce(with_check,'')) ILIKE '%is_admin%') OR has_table_privilege('authenticated','public.holdings','TRUNCATE') THEN RAISE EXCEPTION 'legacy privacy preservation failed'; END IF; END $$;